<?php
require_once __DIR__.'/../includes/auth.php';requireRole(['admin','editor']);$errors=[];
if(isPost()){verifyCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if(in_array($action,['add','edit'],true)){$name=trim($_POST['name']??'');if(mb_strlen($name)<2)$errors[]='اسم التصنيف مطلوب.';if(!$errors){$slug=uniqueSlug('categories',$name,$id?:null);if($action==='add'){db()->prepare('INSERT INTO categories(name,slug,description,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())')->execute([$name,$slug,trim($_POST['description']??'')]);}else{db()->prepare('UPDATE categories SET name=?,slug=?,description=?,updated_at=NOW() WHERE id=?')->execute([$name,$slug,trim($_POST['description']??''),$id]);}flash('success','تم حفظ التصنيف.');redirect(url('admin/categories.php'));}}elseif($action==='delete'){$s=db()->prepare('SELECT COUNT(*) FROM news WHERE category_id=?');$s->execute([$id]);if($s->fetchColumn())flash('danger','لا يمكن حذف تصنيف مرتبط بأخبار. انقل الأخبار أولًا.');else{db()->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('success','تم حذف التصنيف.');}redirect(url('admin/categories.php'));}}
$q=trim($_GET['q']??'');$s=db()->prepare('SELECT c.*,COUNT(n.id) news_count FROM categories c LEFT JOIN news n ON n.category_id=c.id WHERE c.name LIKE ? GROUP BY c.id ORDER BY c.name');$s->execute(["%{$q}%"]);$rows=$s->fetchAll();$edit=null;if($eid=(int)($_GET['edit']??0)){$s=db()->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$eid]);$edit=$s->fetch();}$pageTitle='التصنيفات';require __DIR__.'/includes/header.php';?>
<div class="row g-4"><div class="col-lg-4"><div class="card stat-card"><div class="card-body"><h5 class="fw-bold mb-3"><?=$edit?'تعديل التصنيف':'إضافة تصنيف'?></h5><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="form-label">الاسم</label><input class="form-control mb-3" name="name" required value="<?=e($edit['name']??'')?>"><label class="form-label">الوصف</label><textarea class="form-control mb-3" name="description" rows="4"><?=e($edit['description']??'')?></textarea><button class="btn btn-primary w-100">حفظ</button></form></div></div></div><div class="col-lg-8"><div class="card stat-card"><div class="card-body"><form class="mb-3"><input class="form-control" name="q" placeholder="بحث في التصنيفات" value="<?=e($q)?>"></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>الاسم</th><th>الرابط</th><th>عدد الأخبار</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-bold"><?=e($r['name'])?></td><td><code><?=e($r['slug'])?></code></td><td><?=$r['news_count']?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">تعديل</a><form class="d-inline" method="post"><?=csrfField()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="حذف التصنيف؟">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/includes/footer.php';?>
